long Hours(int[] piles, int k) {
    long hours = 0;                       // up to 10⁴ · 10⁹ — needs long
    foreach (int p in piles)
        hours += (p - 1) / k + 1;         // ⌈p / k⌉ without double, p ≥ 1
    return hours;
}
// Hours([3, 6, 7, 11], 4) == 8, Hours([3, 6, 7, 11], 3) == 10

