// fits is monotonic: false…false true…true, and fits(hi) == true
int MinTrue(int lo, int hi, Func<int, bool> fits) {
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (fits(mid)) hi = mid;      // mid works — the answer is not to the right
        else lo = mid + 1;            // mid is too small — the answer is to the right
    }
    return lo;
}

