bool CanShip(int[] weights, int days, int cap) {   // cap >= max(weights)
    int used = 1, load = 0;
    foreach (int w in weights) {
        if (load + w > cap) { used++; load = 0; }  // does not fit — a new day
        load += w;
    }
    return used <= days;
}
// MinTrue(weights.Max(), weights.Sum(), cap => CanShip(weights, days, cap))

